/** Input/Output schema — 依据本体 DataObjects 定义。 */
interface CreateJDAgentInput {
  job_requisition_id: string; // 需求ID（REQUIREMENT_LOGGED / CLARIFICATION_READY 事件传入） (源: Job_Requisition.job_requisition_id)
  job_posting_id: string; // 职位发布ID（JD_REJECTED 事件传入） (源: Job_Posting.job_posting_id)
}

interface CreateJDAgentOutput {
